import pyAether as pyScript

def count_specific_instances(lib_name: str, cell_name: str, view_name: str, target_master_cell: str) -> int:
    cv = pyScript.CellView(lib_name=lib_name, cell_name=cell_name, view_name=view_name)
    if cv is None:
        return 0
    count = 0
    for inst in cv.get_instances():
        if inst.master_cell_name == target_master_cell:
            count += 1
    cv.close()
    return count

